import { Minus, Square, X } from "lucide-react";
import { useT } from "../lib/i18n";
// @ts-ignore wailsjs bindings are generated by wails build
import { WindowMinimise, WindowToggleMaximise, Quit } from "../../wailsjs/runtime";

// Frameless-window caption buttons. The whole strip above them carries
// --wails-draggable: drag so the user can move the window by its title bar.
export default function WindowControls() {
  const t = useT();
  return (
    <div className="flex items-center gap-1">
      <button
        type="button"
        aria-label={t("window.minimize")}
        title={t("window.minimize")}
        onClick={() => WindowMinimise()}
        className="flex h-8 w-8 items-center justify-center rounded text-white/60 hover:bg-white/10 hover:text-white"
      >
        <Minus className="h-3.5 w-3.5" />
      </button>
      <button
        type="button"
        aria-label={t("window.maximize")}
        title={t("window.maximize")}
        onClick={() => WindowToggleMaximise()}
        className="flex h-8 w-8 items-center justify-center rounded text-white/60 hover:bg-white/10 hover:text-white"
      >
        <Square className="h-3 w-3" />
      </button>
      <button
        type="button"
        aria-label={t("window.close")}
        title={t("window.close")}
        onClick={() => Quit()}
        className="flex h-8 w-8 items-center justify-center rounded text-white/60 hover:bg-red-500/80 hover:text-white"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}
